-- SOURCE staff_delegation.sql sha256=7c966f9a366630a325bdbc22bc03848c6c5e7916448ded1936173ef343a6e815
CREATE OR REPLACE FUNCTION public.phase81_manage_staff_permission_grants(
    p_actor_user_id uuid, p_institution_id uuid, p_target_user_id uuid,
    p_permission_codes text[], p_grant boolean
) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE permission_code text; permission_row public.permissions; changed_count integer := 0; grant_id uuid;
BEGIN
    PERFORM public.phase81_assert_institution_admin(p_actor_user_id, p_institution_id);
    IF p_actor_user_id = p_target_user_id THEN
        RAISE EXCEPTION 'Administrators cannot delegate staff permissions to themselves' USING ERRCODE = '42501';
    END IF;
    PERFORM 1 FROM public.users u JOIN public.user_roles ur ON ur.user_id = u.id JOIN public.roles r ON r.id = ur.role_id
    WHERE u.id = p_target_user_id AND u.status = 'active' AND r.name = 'staff' AND r.is_active
      AND ur.scope_type = 'institution' AND ur.scope_id = p_institution_id FOR SHARE OF u, ur, r;
    IF NOT FOUND THEN RAISE EXCEPTION 'Active institution staff member required' USING ERRCODE = '42501'; END IF;
    IF COALESCE(array_length(p_permission_codes, 1), 0) NOT BETWEEN 1 AND 32
        OR cardinality(p_permission_codes) <> (SELECT count(DISTINCT code) FROM unnest(p_permission_codes) code) THEN
        RAISE EXCEPTION 'Supply 1 to 32 unique permission codes' USING ERRCODE = '23514';
    END IF;
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
        'staff-permissions:' || p_institution_id::text || ':' || p_target_user_id::text, 0));
    FOREACH permission_code IN ARRAY p_permission_codes LOOP
        IF permission_code <> ALL(ARRAY[
            'ai.knowledge.create','students.read','students.update','documents.read','documents.create',
            'documents.update','notices.read','notices.create','notices.update'
        ]::text[]) THEN
            RAISE EXCEPTION 'Permission is outside the staff delegation allowlist' USING ERRCODE = '42501';
        END IF;
        SELECT * INTO permission_row FROM public.permissions p WHERE p.code = permission_code FOR SHARE;
        IF NOT FOUND OR (p_grant AND NOT permission_row.is_active) THEN
            RAISE EXCEPTION 'Unknown or inactive permission' USING ERRCODE = '23514';
        END IF;
        grant_id := NULL;
        IF p_grant THEN
            INSERT INTO public.user_permission_grants(user_id, institution_id, permission_id, granted_by)
            VALUES (p_target_user_id, p_institution_id, permission_row.permission_id, p_actor_user_id)
            ON CONFLICT (user_id, institution_id, permission_id) WHERE revoked_at IS NULL DO NOTHING
            RETURNING user_permission_grants.grant_id INTO grant_id;
        ELSE
            UPDATE public.user_permission_grants g SET revoked_by = p_actor_user_id, revoked_at = clock_timestamp()
            WHERE g.user_id = p_target_user_id AND g.institution_id = p_institution_id
              AND g.permission_id = permission_row.permission_id AND g.revoked_at IS NULL RETURNING g.grant_id INTO grant_id;
        END IF;
        IF grant_id IS NOT NULL THEN
            INSERT INTO public.admin_audit_log(actor_user_id, institution_id, action, table_name, record_id, record_data, status)
            VALUES (p_actor_user_id, p_institution_id, CASE WHEN p_grant THEN 'permission.grant' ELSE 'permission.revoke' END,
                'user_permission_grants', grant_id::text,
                jsonb_build_object('target_user_id', p_target_user_id, 'permission_code', permission_code, 'source', 'direct'), 'success');
            changed_count := changed_count + 1;
        END IF;
    END LOOP;
    RETURN changed_count;
END;
$$;
REVOKE ALL ON FUNCTION public.phase81_manage_staff_permission_grants(uuid,uuid,uuid,text[],boolean)
    FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.phase81_manage_staff_permission_grants(uuid,uuid,uuid,text[],boolean) TO service_role;

-- SOURCE permissions.sql sha256=4b8e217a4aa0dd861ce3a564e730b6658132296827665fbab49c26d919c3131a
-- Account-role assignments and identity/approval permissions stay intact.
-- Remove only grants for the explicitly retired academic permission families.
DELETE FROM public.user_permission_grants WHERE permission_id IN(SELECT permission_id FROM academic_decommission_permissions);
DELETE FROM public.role_permissions WHERE permission_id IN(SELECT permission_id FROM academic_decommission_permissions);
DELETE FROM public.permissions WHERE permission_id IN(SELECT permission_id FROM academic_decommission_permissions);

-- SOURCE approval_adapter.sql sha256=6f47cdb4946d9d3415b40722f4b277faee21ded4cf1726e4934e1394edd60039
-- The observed deployment has never installed the optional B05 invitation
-- draft/approval repair. Keep existing approval routines untouched; provide
-- only the identity/account transaction required by the retained backend.
DO $adapter$
BEGIN
    IF to_regprocedure('public.b05_approve_student(uuid,uuid,uuid,uuid)') IS NOT NULL THEN RETURN; END IF;
    EXECUTE $definition$
    CREATE FUNCTION public.b05_approve_student(
        p_student_id uuid, p_institution_id uuid, p_actor_user_id uuid, p_actor_auth_user_id uuid
    ) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $body$
    DECLARE student public.students; organization uuid; student_role uuid;
    BEGIN
        IF COALESCE(auth.role(),'') <> 'service_role' THEN
            RAISE EXCEPTION 'Authorized student approver required' USING ERRCODE='42501';
        END IF;
        PERFORM 1 FROM public.users u JOIN public.user_roles ur ON ur.user_id=u.id
        JOIN public.roles r ON r.id=ur.role_id JOIN public.institutions i ON i.institution_id=p_institution_id
        JOIN public.organizations o ON o.organization_id=i.organization_id
        WHERE u.id=p_actor_user_id AND u.auth_user_id=p_actor_auth_user_id AND u.status='active'
          AND r.name IN('admin','staff') AND r.is_active AND ur.scope_type='institution'
          AND ur.scope_id=p_institution_id AND ur.scope_organization_id=i.organization_id
          AND i.status='active' AND i.is_active AND o.status='active' FOR SHARE OF u,ur,r,i,o;
        IF NOT FOUND THEN RAISE EXCEPTION 'Authorized student approver required' USING ERRCODE='42501'; END IF;
        PERFORM 1 FROM public.user_roles ur JOIN public.roles r ON r.id=ur.role_id
        JOIN public.role_permissions rp ON rp.role_id=r.id JOIN public.permissions p ON p.permission_id=rp.permission_id
        WHERE ur.user_id=p_actor_user_id AND ur.scope_type='institution' AND ur.scope_id=p_institution_id
          AND r.name IN('admin','staff') AND r.is_active AND p.is_active
          AND p.code IN('students.approve','students.*','*') FOR SHARE OF ur,r,rp,p;
        IF NOT FOUND THEN
            PERFORM 1 FROM public.user_permission_grants g JOIN public.permissions p USING(permission_id)
            WHERE g.user_id=p_actor_user_id AND g.institution_id=p_institution_id AND g.revoked_at IS NULL
              AND p.is_active AND p.code IN('students.approve','students.*','*') FOR SHARE OF g,p;
            IF NOT FOUND THEN RAISE EXCEPTION 'Student approval permission required' USING ERRCODE='42501'; END IF;
        END IF;
        SELECT * INTO student FROM public.students
        WHERE student_id=p_student_id AND institution_id=p_institution_id FOR UPDATE;
        IF NOT FOUND THEN RETURN jsonb_build_object('not_found',true); END IF;
        IF student.approval_status NOT IN('pending','approved') THEN RETURN jsonb_build_object('conflict',true); END IF;
        SELECT organization_id INTO organization FROM public.institutions
        WHERE institution_id=p_institution_id AND status='active' AND is_active FOR SHARE;
        SELECT id INTO student_role FROM public.roles WHERE name='student' AND is_active FOR SHARE;
        PERFORM 1 FROM public.users WHERE id=student.user_id AND status='active' AND auth_user_id IS NOT NULL
          AND lower(email)=lower(student.email) FOR UPDATE;
        IF NOT FOUND OR student_role IS NULL OR organization IS NULL THEN
            RAISE EXCEPTION 'Student provisioning prerequisites missing' USING ERRCODE='23514';
        END IF;
        INSERT INTO public.user_roles(user_id,role_id,scope_type,scope_id,scope_organization_id)
        VALUES(student.user_id,student_role,'institution',p_institution_id,organization)
        ON CONFLICT(user_id,role_id) DO NOTHING;
        IF NOT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=student.user_id AND role_id=student_role
            AND scope_type='institution' AND scope_id=p_institution_id AND scope_organization_id=organization) THEN
            RAISE EXCEPTION 'Student role scope conflict' USING ERRCODE='42501';
        END IF;
        UPDATE public.students SET approval_status='approved' WHERE student_id=p_student_id RETURNING * INTO student;
        -- The student row lock serializes all calls for this identity. Reuse
        -- the existing action/snapshot contract without adding invitation or
        -- decision-key schema to deployments that never installed B05.
        IF NOT EXISTS(SELECT 1 FROM public.admin_audit_log WHERE institution_id=p_institution_id
            AND action='student.approve' AND table_name='students' AND record_id=p_student_id::text
            AND record_data->>'role_granted'='true' AND status='success') THEN
            INSERT INTO public.admin_audit_log(actor_user_id,institution_id,action,table_name,record_id,record_data,status)
            VALUES(p_actor_user_id,p_institution_id,'student.approve','students',p_student_id::text,
                jsonb_build_object('approval_status','approved','role_granted',true),'success');
        END IF;
        RETURN jsonb_build_object('student',to_jsonb(student),'role_granted',true,'audit_persisted',true);
    END;
    $body$;
    $definition$;
    EXECUTE 'REVOKE ALL ON FUNCTION public.b05_approve_student(uuid,uuid,uuid,uuid) FROM PUBLIC,anon,authenticated';
    EXECUTE 'GRANT EXECUTE ON FUNCTION public.b05_approve_student(uuid,uuid,uuid,uuid) TO service_role';
END;
$adapter$;

-- SOURCE verification.sql sha256=c762348c2861535c2650af0f93451fa1fc70995e6cf9af29f394bc1fc7381cb3
DO $$
DECLARE item record; current_rows jsonb; projection text; predicate text;
BEGIN
    IF EXISTS (SELECT 1 FROM academic_decommission_tables t WHERE to_regclass(format('public.%I',t.name)) IS NOT NULL)
        OR EXISTS (SELECT 1 FROM pg_catalog.pg_proc p WHERE p.pronamespace='public'::regnamespace
            AND p.proname IN(SELECT name FROM academic_decommission_functions)) THEN
        RAISE EXCEPTION 'Academic runtime objects remain after decommission';
    END IF;
    IF EXISTS (SELECT 1 FROM public.permissions
        WHERE code ~ '^(academic\.|attendance\.|results\.|faculty\.assignments\.|departments\.|courses\.|subjects\.|semesters\.|academic_years\.)') THEN
        RAISE EXCEPTION 'Retired academic permission codes remain';
    END IF;
    FOR item IN SELECT * FROM academic_decommission_preserved LOOP
        projection := CASE WHEN item.schema_name='public' AND item.table_name='students'
            THEN 'to_jsonb(t) - ARRAY[''program_id'',''academic_year_id'']' ELSE 'to_jsonb(t)' END;
        predicate := CASE WHEN item.schema_name='public' AND item.table_name IN('permissions','role_permissions','user_permission_grants')
            THEN 'WHERE permission_id NOT IN(SELECT permission_id FROM academic_decommission_permissions)' ELSE '' END;
        EXECUTE format('SELECT COALESCE(jsonb_agg(row ORDER BY row::text),''[]''::jsonb) FROM '
            || '(SELECT %s AS row FROM %I.%I t %s) source',projection,item.schema_name,item.table_name,predicate) INTO current_rows;
        IF current_rows IS DISTINCT FROM item.rows THEN
            RAISE EXCEPTION 'Preserved data changed in %.%; decommission rolled back',item.schema_name,item.table_name;
        END IF;
    END LOOP;
    IF EXISTS (SELECT 1 FROM academic_decommission_routines snapshot
        LEFT JOIN pg_catalog.pg_proc p ON p.oid=snapshot.oid
        WHERE p.oid IS NULL OR pg_get_functiondef(p.oid) IS DISTINCT FROM snapshot.definition) THEN
        RAISE EXCEPTION 'A preserved account/nonacademic function changed';
    END IF;
END;
$$;
NOTIFY pgrst, 'reload schema';
COMMIT;
